class _HomePageState extends State<HomePage>{final db=Supabase.instance.client;final cart=<CartItem>[];List<Product>products=[];bool loading=true;String search='';int tab=0;double get total=>cart.fold(0,(s,x)=>s+x.product.sellPrice*x.qty);@override void initState(){super.initState();loadProducts();}Future<void>loadProducts()async{setState(()=>loading=true);try{final rows=await db.from('products').select('id,name,barcode,sell_price,buy_price,stock,min_stock,category').order('name');products=(rows as List).map((r)=>Product.fromMap(Map<String,dynamic>.from(r))).toList();}catch(e){_snack('تعذر تحميل المنتجات: $e');}if(mounted)setState(()=>loading=false);}void _snack(String s){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(s)));}List<Product>get filtered=>products.where((p){final q=search.toLowerCase();return p.name.toLowerCase().contains(q)||(p.barcode??'').contains(search);}).toList();void add(Product p){if(p.stock<=0){_snack('المنتج سالا من الستوك');return;}final i=cart.indexWhere((x)=>x.product.id==p.id);setState((){if(i>=0){if(cart[i].qty<p.stock)cart[i].qty++;}else cart.add(CartItem(p));});}void changeQty(CartItem x,int delta){setState(()=>x.qty=(x.qty+delta).clamp(1,x.product.stock));}Future<void>scan()async{final code=await Navigator.push<String>(context,MaterialPageRoute(builder:(_)=>const ScannerPage()));if(code==null)return;final row=await db.from('products').select('id,name,barcode,sell_price,buy_price,stock,min_stock,category').eq('barcode',code).maybeSingle();if(row==null){_snack('Barcode غير موجود');return;}add(Product.fromMap(Map<String,dynamic>.from(row)));}
Future<void>checkout()async{if(cart.isEmpty)return;final checkoutTotal=total;final result=await showDialog<Map<String,dynamic>>(context:context,builder:(c)=>PaymentDialog(total:checkoutTotal));if(result==null)return;final method=result['method'] as String;final received=(result['received'] as num).toDouble();try{final items=cart.map((x)=>{'product_id':x.product.id,'qty':x.qty}).toList();await db.rpc('pos_checkout',params:{'p_subtotal':checkoutTotal,'p_discount':0,'p_total':checkoutTotal,'p_payment_method':method,'p_items':items,'p_customer_id':null});final change=method=='cash'?received-checkoutTotal:0;setState(()=>cart.clear());await loadProducts();if(mounted)showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('تم البيع بنجاح'),content:Text('المجموع: ${checkoutTotal.toStringAsFixed(2)} MAD\nالمستلم: ${received.toStringAsFixed(2)} MAD\nالباقي: ${change.toStringAsFixed(2)} MAD'),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('حسناً'))]));}catch(e){_snack('تعذر إتمام البيع: $e');}}
Future<void>closeShift()async{final actualCtrl=TextEditingController();final actual=await showDialog<double>(context:context,builder:(c)=>AlertDialog(title:const Text('إغلاق الصندوق'),content:TextField(controller:actualCtrl,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Cash الموجود فعلياً (MAD)')),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(c,double.tryParse(actualCtrl.text.replaceAll(',','.'))),child:const Text('إغلاق'))]));actualCtrl.dispose();if(actual==null)return;try{final shift=await db.from('cash_register_shifts').select('opening_cash,opened_at').eq('id',widget.shiftId).single();final opened=DateTime.parse('${shift['opened_at']}').toUtc();final sales=await db.from('sales').select('total,payment_method').eq('user_id',db.auth.currentUser!.id).eq('payment_method','cash').gte('created_at',opened.toIso8601String());final expected=(shift['opening_cash'] as num).toDouble()+sales.fold<double>(0,(s,r)=>s+((r['total'] as num?)?.toDouble()??0));await db.from('cash_register_shifts').update({'status':'closed','closed_at':DateTime.now().toUtc().toIso8601String(),'closed_by':db.auth.currentUser!.id,'expected_cash':expected,'actual_cash':actual,'difference':actual-expected}).eq('id',widget.shiftId);await db.auth.signOut();}catch(e){_snack('تعذر إغلاق الصندوق: $e');}}
